"""Generate plain, deployable HTML. Python is only needed when regenerating pages."""
import json,html
from pathlib import Path
from urllib.parse import quote
ROOT=Path(__file__).resolve().parent.parent
P=json.loads((ROOT/'assets/data/products.json').read_text())
e=lambda s:html.escape(str(s),quote=True)
categories=list(dict.fromkeys(p['category'] for p in P))
def swatch(c,base=''):
 s=c.get('swatch','');return 'background-image:url('+e(s if s.startswith('data:') else base+s)+')' if s else 'background:#ddd'
def photo(p,base='',code=None):
 c=next((c for c in p['colors'] if c['code']==code),p['colors'][0]);return base+c['image'] if c.get('image') else ''
def layout(title,body,base='',description='Logózott textilek, hímzés és egyedi bögrék vállalkozásoknak. Céges megjelenés összesen 5 darabtól.',page=''):
 data_script=f'<script src="{base}assets/data/products.js" defer></script>' if page in ['product','quote'] else ''
 return f'''<!doctype html><html lang="hu"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{e(description)}"><meta name="theme-color" content="#242826"><title>{e(title)} | Cégforma</title><link rel="icon" href="{base}assets/images/cegforma-logo.webp" type="image/webp"><link rel="stylesheet" href="{base}assets/fonts.css"><link rel="stylesheet" href="{base}assets/styles.css?v=2">{data_script}<script src="{base}assets/app.js?v=2" defer></script></head><body data-page="{page}" data-base="{base}"><noscript><style>.nav-links{{display:flex;position:static;flex-wrap:wrap}}.nav{{height:auto;min-height:88px;flex-wrap:wrap;padding-bottom:12px}}.menu-toggle{{display:none}}</style></noscript><a class="skip" href="#main">Ugrás a tartalomra</a><header class="site-header"><div class="wrap nav"><a class="brand" href="{base}index.html" aria-label="Cégforma – kezdőlap"><img src="{base}assets/images/cegforma-logo.webp" width="110" height="76" alt="Cégforma – emblémázás, hímzés"></a><span class="nav-descriptor">TEXTIL &amp; EMBLÉMÁZÁS<br>EGYEDI TERMÉKEK 2019 ÓTA</span><button class="menu-toggle" aria-expanded="false" aria-controls="navigation">Menü <span aria-hidden="true">☰</span></button><nav class="nav-links" id="navigation" aria-label="Fő navigáció"><a href="{base}katalogus.html">Termékek</a><a href="{base}index.html#szolgaltatasok">Emblémázás</a><a href="{base}index.html#rolunk">Rólunk</a><a href="{base}index.html#kapcsolat">Kapcsolat</a><a class="button small" href="{base}ajanlatkeres.html">Árajánlatot kérek <span aria-hidden="true">↗</span></a></nav></div></header><main id="main">{body}</main><footer id="kapcsolat"><div class="wrap"><div class="footer-top"><div><img src="{base}assets/images/cegforma-logo.webp" width="130" height="98" alt="Cégforma"><p>Textilre gondolva.<br>Cégekre szabva.</p></div><div><h3>Írj nekünk</h3><p><a class="text-link" href="mailto:cegforma@gmail.com">cegforma@gmail.com ↗</a></p><p><span class="pending">Pontos cím: egyeztetés alatt</span></p></div><div><h3>Nézz körül</h3><p><a href="{base}katalogus.html">Termékkatalógus</a></p><p><a href="{base}ajanlatkeres.html">Árajánlatkérés</a></p><p><a href="{base}adatkezeles.html">Adatkezelési tájékoztató – előkészítés alatt</a></p></div></div><div class="footer-bottom"><span>© 2026 Cégforma · Emblémázás és hímzés</span><span>TEXTIL / DTF / HÍMZÉS / SZUBLIMÁCIÓ</span></div></div></footer></body></html>'''
def crumb(text,base=''):
 return f'<div class="breadcrumb"><a href="{base}index.html">Kezdőlap</a> &nbsp; / &nbsp; {text}</div>'
def card(p):
 c=next((c for c in p['colors'] if c['code']=='01'),next(c for c in p['colors'] if c.get('image')))
 return f'''<article class="product-card" data-category="{e(p['category'])}" data-search="{e(p['name']+' '+p['category']+' '+p['sku'])}"><a class="product-photo" href="termekek/{p['id']}.html"><img src="{e(c['image'])}" alt="{e(p['name']+' – '+c['label'])}" width="400" height="480" loading="lazy"></a><div class="product-card-info"><p class="meta">{e(p['category'])} <span>#{e(p['sku'])}</span></p><h2><a href="termekek/{p['id']}.html">{e(p['name'])}</a></h2><div class="card-swatches" aria-label="{len(p['colors'])} színváltozat">{''.join(f'<span style="{swatch(c)}" title="{e(c["label"])}"></span>' for c in p['colors'])}</div><p class="price">Nettó ár: egyeztetés alatt</p><a class="card-link" href="termekek/{p['id']}.html">Megnézem a terméket <span aria-hidden="true">↗</span></a></div></article>'''
category_rows=''
for i,cat in enumerate(categories):
 ps=[p for p in P if p['category']==cat];p=ps[0]
 image=photo(p,code='01')
 category_rows+=f'<a class="category-row" href="katalogus.html?kategoria={quote(cat)}" data-preview="{image}" data-caption="{e(p["name"])}" data-index="{i+1:02d}"><span class="row-no">{i+1:02d}</span><img src="{image}" width="90" height="100" alt="" loading="lazy"><h3>{e(cat)}</h3><span class="row-count">{len(ps):02d} termék</span><span class="row-arrow" aria-hidden="true">↗</span></a>'
home=(ROOT/'templates/home.html').read_text().replace('{{category_rows}}',category_rows)
(ROOT/'index.html').write_text(layout('A céged viselhető oldala',home,page='home'))
filters='<a href="katalogus.html" data-filter="" aria-current="true">Összes termék <span>15</span></a>'+''.join(f'<a href="katalogus.html?kategoria={quote(cat)}" data-filter="{e(cat)}" aria-current="false">{e(cat)} <span>{sum(p["category"]==cat for p in P)}</span></a>' for cat in categories)
catalog=f'''<div class="wrap">{crumb('Termékkatalógus')}<div class="page-intro"><p class="eyebrow">VÁLOGATOTT ALAPDARABOK / 15 TERMÉK</p><h1>A textiljegyzék.</h1><p>Válassz fazont és színt, nézd meg a méreteket, és állítsd össze az ajánlatkérésed. Minimum mennyiség: összesen 5 darab.</p></div><div class="catalog-layout"><aside class="filters"><h2>Termékkategóriák</h2><nav class="filter-links" aria-label="Termékkategóriák">{filters}</nav></aside><div><div class="catalog-tools"><p id="result-count" role="status">15 termék</p><label><span class="sr-only">Keresés név vagy cikkszám alapján</span><input type="search" id="search" placeholder="Név vagy cikkszám…" aria-label="Keresés név vagy cikkszám alapján"></label></div><div class="product-grid">{''.join(card(p) for p in P)}</div><p class="empty" id="no-results" hidden>Nincs találat. Próbálj másik keresést vagy kategóriát.</p></div></div></div>'''
(ROOT/'katalogus.html').write_text(layout('Termékkatalógus',catalog,page='catalog'))
(ROOT/'termekek').mkdir(exist_ok=True)
for p in P:
 c=next((c for c in p['colors'] if c['code']=='01'),next(c for c in p['colors'] if c.get('image')));base='../'
 sw=''.join(f'<button type="button" class="swatch" data-color="{e(x["code"])}" aria-label="{e(x["label"])}" title="{e(x["label"])}" aria-pressed="{str(x==c).lower()}"><span style="{swatch(x,base)}"></span></button>' for x in p['colors'])
 sizes=f'<p class="pending">Méretadatok: pontosításra várnak</p><p class="form-help">A beszállító mérettáblázatként termékadatlapot ad meg; részletes méretsor nem szerepel benne.</p>' if p.get('sizePending') else f'<a href="../{p["sizeChart"]}" target="_blank" rel="noopener"><img class="size-chart" src="../{p["sizePreview"]}" alt="{e(p["name"])} – gyártói mérettáblázat és mérési ábra. Nagyításhoz nyisd meg a PDF-et." loading="lazy"></a>'
 extra=f'''<section class="cta-band" style="margin-bottom:65px"><div><h2>Teljes termékkínálat</h2><p>Még több fazont és színt keresel? Online katalógusunkban további pólók, galléros pólók és más ruházati termékek közül választhatsz, a saját árainkkal.</p><p>Válaszd ki a neked tetsző terméket, és küldd el nekünk a cikkszámát, a választott színt, a méreteket és a darabszámot. A kívánt nyomásra vagy hímzésre egyedi ajánlatot adunk.</p></div><a class="button dark" style="flex-shrink:0" href="https://onlinecatalog.malfini.com/01236983/hu/catalog" target="_blank" rel="noopener">Megnézem a teljes kínálatot ↗</a></section>''' if p['brand']=='Malfini' else ''
 body=f'''<div class="wrap" data-product="{p['id']}">{crumb('<a href="../katalogus.html">Termékkatalógus</a> &nbsp; / &nbsp; '+e(p['name']),base)}<section class="detail"><div class="detail-photo"><img id="variant-image" src="{photo(p,base,c['code'])}" alt="{e(p['name']+' – '+c['label'])}" width="400" height="480"><p id="variant-missing" class="image-pending" hidden>Ehhez a színhez a termékkép még feltöltésre vár.</p></div><div><p class="eyebrow">{e(p['category'])}</p><h1>{e(p['name'])}</h1><p class="small-note">{e(p['brand'])} · Cikkszám: {e(p['sku'])}</p><p class="detail-description">{e(p['description'])}</p><p class="pending">Nettó ár: egyeztetés alatt</p><p class="color-label" aria-live="polite">Kiválasztott szín: <strong id="selected-color">{e(c['label'])}</strong></p><div class="swatches" role="group" aria-label="Választható színek">{sw}</div><p class="form-help">A képernyőn látható színek tájékoztató jellegűek. A Malfini-színeket a beszállító kódjával jelöljük.</p><a class="button" id="product-quote" href="../ajanlatkeres.html?termek={p['id']}&amp;szin={quote(c['code'])}">Erre a termékre kérek ajánlatot ↗</a><p class="small-note">Minimum összesen 5 darab, akár többféle termékből.<br>Az ajánlatkérés nem jelent végleges megrendelést.</p></div></section><div class="detail-extra"><section><h2>Termékinformációk</h2><ul class="spec-list">{''.join('<li>'+e(s)+'</li>' for s in p['specs'])}</ul><p class="form-help">Forrás: <a class="text-link" href="{e(p['source'])}" target="_blank" rel="noopener">{e(p['brand'])} termékoldal ↗</a><br>Ellenőrizve: 2026. október 6.</p><p class="small-note">Az emblémázás módját a grafikád és a termék alapján egyeztetjük.</p></section><section><h2>Mérettáblázat</h2>{sizes}<a class="text-link" href="../{p['sizeChart']}" target="_blank" rel="noopener">Gyártói {'adatlap' if p.get('sizePending') else 'mérettáblázat'} megnyitása (PDF) ↗</a></section></div>{extra}</div>'''
 (ROOT/'termekek'/f'{p["id"]}.html').write_text(layout(p['name'],body,base,p['description'],page='product'))
# The form intentionally has no network submission endpoint in this first version.
form='''<div class="wrap">'''+crumb('Árajánlatkérés')+'''<div class="page-intro"><p class="eyebrow">A te csapatodra szabva</p><h1>A te munkalapod.</h1><p>Töltsd ki, amit már tudsz. A részleteket később is egyeztethetjük. Az árajánlatkérés nem jelent végleges megrendelést.</p></div><div class="form-layout"><div><div class="notice"><strong>Előzetes változat – az e-mail-küldés még nincs bekötve.</strong><br>Az űrlapból másolható összesítő készül. Az adatok nem kerülnek elküldésre vagy mentésre; az összesítőt saját leveleződből küldheted el a cegforma@gmail.com címre.</div><noscript><p class="no-script">Az összesítőhöz engedélyezd a JavaScriptet, vagy írj közvetlenül a cegforma@gmail.com címre.</p></noscript><form class="quote-form" id="quote-form"><fieldset><legend><span>01</span>Kapcsolattartási adatok</legend><div class="field-grid"><label class="field">Kapcsolattartó neve *<input name="contact" autocomplete="name" required maxlength="120"></label><label class="field">Cégnév *<input name="company" autocomplete="organization" required maxlength="160"></label><label class="field">Telefonszám *<input name="phone" type="tel" autocomplete="tel" required maxlength="40"></label><label class="field">E-mail-cím *<input name="email" type="email" autocomplete="email" required maxlength="200"></label></div></fieldset><fieldset><legend><span>02</span>A kiválasztott termékek</legend><div id="product-rows"></div><button type="button" class="button outline small" id="add-product">+ Másik termék hozzáadása</button><p class="form-help" id="quantity-help">Minimum rendelési mennyiség: összesen 5 darab. Hozzávetőleges mennyiség is megadható.</p><p class="small-note" id="total-quantity" role="status">Összesen: 0 darab</p></fieldset><fieldset><legend><span>03</span>Emblémázás</legend><div class="field-grid"><label class="field">Technológia<select name="technology"><option value="">Még nem választottam</option><option>DTF nyomtatás</option><option>Hímzés</option><option>Segítséget kérek a választáshoz</option></select></label><label class="field">Minta helye<select name="placement" id="placement"><option value="">Később egyeztetjük</option><option>Elöl</option><option>Hátul</option><option>Mindkét oldalon</option></select></label><label class="field" id="front-field" hidden>Elülső grafika kívánt magassága (cm)<input type="number" min="0.1" step="0.1" name="frontHeight" disabled></label><label class="field" id="back-field" hidden>Hátsó grafika kívánt magassága (cm)<input type="number" min="0.1" step="0.1" name="backHeight" disabled></label></div><p class="form-help" id="ratio-note" hidden>A grafika szélessége az eredeti képarányhoz igazodik.</p><p class="form-help">Több termék eltérő emblémázási igényét a megjegyzésben adhatod meg.</p></fieldset><fieldset><legend><span>04</span>Megjegyzés</legend><label class="field">Egyéb elképzelések, kérések<textarea name="notes" rows="5" maxlength="5000" placeholder="A minta pontos helye, egyéb kérés, kívánt elkészülési időpont…"></textarea></label></fieldset><p class="form-help">A *-gal jelölt mezők kötelezők. Fájlfeltöltés ebben a változatban nincs. Az adatkezelési tájékoztató előkészítés alatt áll; az online beküldés később válik elérhetővé.</p><button class="button" type="submit" id="preview-button" disabled>Ajánlatkérés összesítése ↗</button><section class="preview" id="quote-preview" hidden aria-labelledby="preview-heading"><h2 id="preview-heading" tabindex="-1">Az ajánlatkérésed összesítője</h2><p class="form-help">Ez még nem lett elküldve. Másold ki, majd küldd el e-mailben.</p><label class="field">Másolható szöveg<textarea id="preview-text" readonly></textarea></label><div class="actions"><button type="button" class="button dark small" id="copy-quote">Összesítő másolása</button><a class="text-link" href="mailto:cegforma@gmail.com?subject=C%C3%A9gforma%20%E2%80%93%20%C3%81raj%C3%A1nlatk%C3%A9r%C3%A9s">Levelező megnyitása ↗</a></div><p class="form-help" id="copy-status" role="status"></p></section></form></div><aside class="summary-aside"><p class="eyebrow">Árajánlatkérés</p><h2>Kezdjük azzal,<br>amit már tudsz.</h2><ol><li>Add meg a terméket, a színt és a darabszámot.</li><li>Írd le, milyen emblémázást szeretnél.</li><li>A többit közösen pontosítjuk.</li></ol><p>Kérdésed van?</p><p><a class="text-link" href="mailto:cegforma@gmail.com">cegforma@gmail.com ↗</a></p></aside></div></div>'''
(ROOT/'ajanlatkeres.html').write_text(layout('Árajánlatkérés',form,page='quote'))
(ROOT/'adatkezeles.html').write_text(layout('Adatkezelési tájékoztató – előkészítés alatt','<section class="wrap section"><p class="eyebrow">Ideiglenes helyőrző</p><h1>Adatkezelési tájékoztató</h1><p style="margin-top:25px" class="pending">A végleges, jóváhagyott tájékoztató még nem érkezett meg.</p><p style="margin-top:25px">Az első változat űrlapja csak a böngésződben állít össze másolható szöveget. Nem továbbítja és nem menti a megadott adatokat. Az e-mailes beküldés és a szükséges adatkezelési mezők a végleges tájékoztató alapján kerülnek kialakításra.</p><p>Kapcsolat: <a class="text-link" href="mailto:cegforma@gmail.com">cegforma@gmail.com</a></p></section>'))
(ROOT/'assets/data/products.js').write_text('window.CEGFORMA_PRODUCTS = '+json.dumps(P,ensure_ascii=False,separators=(',',':'))+';\n')
print('Generated 19 HTML pages and browser product data.')
